// ============================================================
// TutorBot · Resolver contexto y ruta
// Responsabilidad: convertir un mensaje suelto de Telegram en un
// CONTEXTO completo (quien escribe, en que paso del wizard va y que
// modulo debe atenderlo). No escribe datos ni envia mensajes.
// ============================================================
const cfg = $('Config').first().json;
const upd = $('Telegram Trigger').first().json;
const msg = upd.message || upd.edited_message || {};
const from = msg.from || {};

const telegram_user = String(from.id || '');
const chat_id = String((msg.chat && msg.chat.id) || from.id || '');
const nombre_telegram = [from.first_name, from.last_name].filter(Boolean).join(' ');
const texto = typeof msg.text === 'string' ? msg.text.trim() : '';

const esComando = texto.startsWith('/');
const partes = texto.split(/\s+/);
const comando = esComando ? partes[0].toLowerCase().replace(/@.*$/, '') : '';
const argumento = esComando ? partes.slice(1).join(' ').trim() : '';

// Lectura defensiva de hojas: si una hoja esta vacia el flujo no debe romperse
function filas(nodo) {
  try {
    return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
}

const sessions    = filas('Leer SESSIONS').filter(r => String(r.telegram_user || '') !== '');
const estudiantes = filas('Leer ESTUDIANTES').filter(r => String(r.id_estudiante || '') !== '');
const tutores     = filas('Leer TUTORES').filter(r => String(r.id_tutor || '') !== '');

const sesionGuardada = sessions.find(s => String(s.telegram_user) === telegram_user) || null;
// Se busca por telegram_user: una vez vinculado, no hay que volver a pedir el codigo.
const estudiante     = estudiantes.find(e => String(e.telegram_user || '') === telegram_user) || null;
// Un tutor se identifica por su telegram_chat_id (campo agregado al modelo, ver docs/02_analisis.md)
const tutor          = tutores.find(t => String(t.telegram_chat_id || '') === telegram_user) || null;

// ---- Estado recuperado de la hoja SESSIONS (persistencia del wizard) ----
let pantalla = sesionGuardada ? String(sesionGuardada.pantalla_actual || 'MENU') : 'INICIO';
let paso     = sesionGuardada ? String(sesionGuardada.paso_actual || '0') : '0';
let datos    = {};
if (sesionGuardada && sesionGuardada.datos_parciales) {
  try { datos = JSON.parse(sesionGuardada.datos_parciales) || {}; } catch (e) { datos = {}; }
}

// ---- TTL: una sesion abandonada no debe "revivir" dias despues ----
const TTL_MIN = Number(cfg.TTL_SESION_MIN || 120);
let sesionExpirada = false;
if (sesionGuardada && sesionGuardada.actualizado_en && pantalla !== 'MENU' && pantalla !== 'INICIO') {
  const t = Date.parse(sesionGuardada.actualizado_en);
  const ahora = Date.parse(cfg.ahora_iso);
  if (!isNaN(t) && !isNaN(ahora) && (ahora - t) / 60000 > TTL_MIN) {
    sesionExpirada = true;
    pantalla = 'MENU'; paso = '0'; datos = {};
  }
}

// ---- Router: comandos globales primero, luego la pantalla del wizard ----
let ruta = 'MENU';
let submodo = 'menu';
let reiniciar = false;

if (!texto) {
  // Foto, sticker, audio, ubicacion: entrada no soportada
  ruta = 'MENU'; submodo = 'no_soportado';
} else if (comando === '/start') {
  reiniciar = true;
  // Sin estudiante vinculado a este Telegram, lo primero es pedir el codigo.
  ruta = estudiante ? 'MENU' : 'REGISTRO';
  submodo = estudiante ? 'bienvenida' : 'inicio';
} else if (comando === '/menu') {
  reiniciar = true; ruta = 'MENU'; submodo = 'menu';
} else if (comando === '/cancelar') {
  reiniciar = true; ruta = 'MENU'; submodo = 'wizard_abortado';
} else if (comando === '/ayuda' || comando === '/help') {
  ruta = 'MENU'; submodo = 'ayuda';
} else if (comando === '/confirmar' || comando === '/finalizar' || comando === '/mis') {
  ruta = 'TUTOR'; submodo = comando.replace('/', '');
} else if (esComando) {
  ruta = 'MENU'; submodo = 'comando_desconocido';
} else if (!estudiante) {
  // Tres pantallas posibles antes de estar identificado.
  ruta = 'REGISTRO';
  if (pantalla === 'REGISTRO_NOMBRE')      submodo = 'guardar_nombre';
  else if (pantalla === 'IDENTIFICACION')  submodo = 'identificar';
  else                                     submodo = 'inicio';
} else if (pantalla === 'INICIO' || pantalla === 'MENU' || pantalla === 'TUTOR') {
  // Solo un numero suelto cuenta como opcion del menu ("2", "2)", "2."). Cualquier
  // otro texto se manda al interprete de IA en vez de adivinar por los digitos sueltos.
  const m = /^\s*([1-9])\s*[).\-]?\s*$/.exec(texto);
  const opcion = m ? m[1] : '';
  if (opcion === '1')      { ruta = 'SOLICITAR'; submodo = 'iniciar'; }
  else if (opcion === '2') { ruta = 'CONSULTAR'; submodo = 'listar'; }
  else if (opcion === '3') { ruta = 'CANCELAR';  submodo = 'listar'; }
  else if (opcion === '4') { ruta = 'MENU';      submodo = 'ayuda'; }
  else                     { ruta = 'MENU';      submodo = 'no_reconocido'; }
} else if (pantalla === 'SOL_MATERIA') {
  ruta = 'SOLICITAR'; submodo = 'materia';
} else if (pantalla === 'SOL_FECHA') {
  ruta = 'SOLICITAR'; submodo = 'fecha';
} else if (pantalla === 'SOL_CONFIRMA') {
  ruta = 'CONFIRMAR'; submodo = 'confirmar';
} else if (pantalla === 'CAN_SELECCION') {
  ruta = 'CANCELAR'; submodo = 'ejecutar';
} else {
  // Pantalla desconocida en la hoja: se reinicia el wizard en lugar de fallar
  reiniciar = true; ruta = 'MENU'; submodo = 'no_reconocido';
}

return [{
  json: {
    telegram_user, chat_id, nombre_telegram,
    texto, comando, argumento,
    ruta, submodo, reiniciar, sesion_expirada: sesionExpirada,
    pantalla_previa: pantalla, paso_previo: paso, datos,
    es_estudiante: !!estudiante,
    id_estudiante: estudiante ? String(estudiante.id_estudiante) : '',
    nombre_estudiante: estudiante ? String(estudiante.nombre) : '',
    es_tutor: !!tutor,
    id_tutor_emisor: tutor ? String(tutor.id_tutor) : '',
    nombre_tutor_emisor: tutor ? String(tutor.nombre) : '',
    ahora_iso: cfg.ahora_iso, hoy: cfg.hoy, hora_actual: cfg.hora_actual
  }
}];

// ============================================================
// TutorBot · Preparar consulta a la IA
// Responsabilidad: decidir SI vale la pena preguntarle al modelo y, en ese
// caso, construir un prompt cerrado (catalogo real + fechas reales).
// No decide nada del negocio: solo prepara texto.
//
// Reglas de contencion (ver docs/06):
//  IA-01 la IA solo se usa cuando el texto libre no encaja en el menu numerico
//  IA-02 nunca se usa en SOL_CONFIRMA: confirmar una reserva exige un numero
//  IA-03 el modelo elige de listas que le damos; no genera datos nuevos
//  IA-04 si MODO_IA esta en off, el sistema funciona igual con menus
// ============================================================
const ctx = $input.first().json;
const cfg = $('Config').first().json;

const MODO_IA   = String(cfg.MODO_IA || 'on').toLowerCase() === 'on';
const HORIZONTE = Number(cfg.DIAS_MAX_ANTICIPACION || 30);
const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// El catalogo es el MISMO que ve el wizard numerico: una sola fuente de verdad
const tutores = filas('Leer TUTORES').filter(t => String(t.id_tutor || '') !== '');
const materiasDe = t => String(t.especialidad_materias || '').split(/[;,|]/).map(s => s.trim()).filter(Boolean);
const catalogo = Array.from(new Map(
  tutores.filter(t => norm(t.estado) === 'activo').flatMap(materiasDe).map(m => [norm(m), m])
).values()).sort((a, b) => a.localeCompare(b, 'es'));

// ---- Fechas de referencia: el modelo ESCOGE de esta lista, no calcula ----
const partesHoy = String(cfg.hoy).split('-').map(Number);
const baseUTC = Date.UTC(partesHoy[0], partesHoy[1] - 1, partesHoy[2]);
const referencia = [];
for (let i = 0; i <= 14; i++) {
  const d = new Date(baseUTC + i * 86400000);
  const iso = d.toISOString().slice(0, 10);
  const etiqueta = i === 0 ? ' (hoy)' : (i === 1 ? ' (manana)' : '');
  referencia.push(iso + ' = ' + DIAS[d.getUTCDay()] + etiqueta);
}

// ------------------------------------------------------------
// ¿Se consulta al modelo?
// ------------------------------------------------------------
const texto = String(ctx.texto || '').trim();
const esNumero = /^\s*\d{1,2}\s*$/.test(texto);
const esFechaISO = /^\d{4}-\d{2}-\d{2}$/.test(texto);

let usar = false;
let motivo = 'no_aplica';

if (!MODO_IA) {
  motivo = 'modo_ia_off';
} else if (!catalogo.length) {
  motivo = 'sin_catalogo';
} else if (!texto || ctx.comando || texto.length < 3 || texto.length > 300) {
  motivo = 'entrada_no_interpretable';
} else if (!ctx.es_estudiante) {
  motivo = 'usuario_no_registrado';   // primero se registra, con reglas
} else if (ctx.pantalla_previa === 'SOL_CONFIRMA') {
  motivo = 'confirmacion_exige_numero';  // IA-02: la reserva se confirma a mano
} else if (ctx.ruta === 'MENU' && ctx.submodo === 'no_reconocido') {
  usar = true; motivo = 'texto_libre_en_menu';
} else if (ctx.pantalla_previa === 'SOL_MATERIA' && !esNumero) {
  usar = true; motivo = 'materia_en_texto_libre';
} else if (ctx.pantalla_previa === 'SOL_FECHA' && !esFechaISO) {
  usar = true; motivo = 'fecha_en_texto_libre';
}

// ------------------------------------------------------------
// Prompt: cerrado, con listas explicitas y prohibiciones explicitas
// ------------------------------------------------------------
const prompt = [
  'Eres el interprete de mensajes de TutorBot, un sistema de asesorias academicas.',
  'Tu UNICA tarea es traducir el mensaje de un estudiante a parametros estructurados.',
  'NO agendas, NO eliges tutor, NO eliges hora, NO consultas disponibilidad, NO confirmas nada.',
  '',
  'Responde EXCLUSIVAMENTE con un objeto JSON valido, sin texto adicional y sin bloques de codigo:',
  '{"intencion":"","materia":"","fecha":"","confianza":0}',
  '',
  'Campos:',
  '- intencion: exactamente uno de solicitar | consultar | cancelar | ayuda | otro',
  '- materia: copiada TAL CUAL de la lista de materias. Si el estudiante nombra algo que no esta en la lista, devuelve "".',
  '- fecha: copiada TAL CUAL de la lista de fechas (formato AAAA-MM-DD). Si no puedes deducirla con certeza, devuelve "".',
  '- confianza: decimal entre 0 y 1 (no porcentaje) que mide SOLO que tan seguro estas de la INTENCION.',
  '',
  'Sobre la confianza, leelo con cuidado:',
  '- Mide unicamente la intencion, NO si pudiste llenar materia o fecha.',
  '- Si entiendes claramente que quiere agendar, consultar o cancelar, la confianza es ALTA (0.9)',
  '  aunque materia y fecha queden vacias. Eso es normal y esperado.',
  '- Baja la confianza solo cuando de verdad no sabes que quiere el estudiante.',
  '',
  'Ejemplos:',
  '  "quiero solicitar una tutoria"        -> {"intencion":"solicitar","materia":"","fecha":"","confianza":0.95}',
  '  "necesito calculo el miercoles"       -> {"intencion":"solicitar","materia":"<de la lista>","fecha":"<de la lista>","confianza":0.9}',
  '  "que tengo agendado"                  -> {"intencion":"consultar","materia":"","fecha":"","confianza":0.95}',
  '  "hola"                                -> {"intencion":"otro","materia":"","fecha":"","confianza":0.2}',
  '',
  'Prohibido inventar materias, fechas, tutores, horarios o estados. Si un dato no esta, dejalo en "".',
  '',
  'MATERIAS DISPONIBLES:',
  catalogo.map(m => '- ' + m).join('\n'),
  '',
  'FECHAS DE REFERENCIA (hoy es ' + cfg.hoy + ', se aceptan hasta ' + HORIZONTE + ' dias adelante):',
  referencia.join('\n'),
  '',
  'MENSAJE DEL ESTUDIANTE:',
  texto
].join('\n');

return [{
  json: Object.assign({}, ctx, {
    ruta_ia: usar ? 'IA' : 'DIRECTO',
    ia_motivo: motivo,
    ia_catalogo: catalogo,
    ia_horizonte: HORIZONTE,
    prompt_ia: prompt
  })
}];

// ============================================================
// TutorBot · Validar interpretacion de la IA
// Responsabilidad: tomar el texto que devolvio Gemini y convertirlo en un
// contexto valido para el motor determinista. Todo lo que el modelo diga
// pasa por aqui; nada de lo que diga llega crudo a los datos.
//
// Reglas de contencion (ver docs/06):
//  IA-05 la materia debe existir EXACTAMENTE en el catalogo real
//  IA-06 la fecha debe pasar las mismas validaciones que la escrita a mano (RN-07)
//  IA-07 dos umbrales, porque enrutar y prellenar no tienen el mismo riesgo:
//        - por debajo de IA_CONFIANZA_PISO se descarta todo
//        - entre el piso y IA_CONFIANZA_MIN se conserva la INTENCION pero se
//          sueltan materia y fecha, y el wizard las vuelve a pedir con sus menus
//  IA-08 cualquier fallo (cuota, timeout, JSON invalido) degrada al menu numerico
//  IA-09 la interpretacion se traduce a la MISMA entrada que habria escrito
//        un humano, para que el motor no tenga un camino especial
// ============================================================
const ctx = $('Preparar consulta IA').first().json;
const cfg = $('Config').first().json;
const entrada = $input.first().json || {};

const MIN_CONF = Number(cfg.IA_CONFIANZA_MIN || 0.6);     // para prellenar materia/fecha
const PISO_CONF = Number(cfg.IA_CONFIANZA_PISO || 0.35);  // para aceptar la intencion
const HORIZONTE = Number(ctx.ia_horizonte || cfg.DIAS_MAX_ANTICIPACION || 30);
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

// ---- 1. Extraer el texto del modelo, sea cual sea la forma del item ----
let crudo = entrada.text;
if (crudo == null) crudo = entrada.output;
if (crudo == null) crudo = entrada.response;
if (crudo == null) crudo = entrada.message;
if (crudo && typeof crudo === 'object') crudo = JSON.stringify(crudo);
crudo = String(crudo == null ? '' : crudo);

// ---- 2. Parseo defensivo: el modelo puede envolver el JSON en ``` o en prosa ----
let ia = null;
let fallo = '';
if (!crudo.trim()) {
  fallo = 'sin_respuesta';           // cuota agotada, timeout o credencial invalida
} else {
  const limpio = crudo.replace(/```[a-z]*/gi, '').trim();
  const ini = limpio.indexOf('{');
  const fin = limpio.lastIndexOf('}');
  if (ini === -1 || fin <= ini) {
    fallo = 'sin_json';
  } else {
    try { ia = JSON.parse(limpio.slice(ini, fin + 1)); }
    catch (e) { fallo = 'json_invalido'; }
  }
}
if (ia && typeof ia !== 'object') { ia = null; fallo = 'json_invalido'; }

// ---- 3. Saneo campo por campo ----
const INTENCIONES = ['solicitar', 'consultar', 'cancelar', 'ayuda', 'otro'];
let intencion = 'otro';
let materia = '';
let fecha = '';
let confianza = 0;

if (ia) {
  const i = norm(ia.intencion);
  intencion = INTENCIONES.includes(i) ? i : 'otro';

  // IA-05: solo vale si coincide con una materia real del catalogo
  const catalogo = Array.isArray(ctx.ia_catalogo) ? ctx.ia_catalogo : [];
  const propuesta = norm(ia.materia);
  if (propuesta) {
    const encontrada = catalogo.find(m => norm(m) === propuesta);
    if (encontrada) materia = encontrada;
    else fallo = fallo || 'materia_inventada';
  }

  // IA-06: misma validacion que la fecha escrita a mano
  const f = String(ia.fecha == null ? '' : ia.fecha).trim();
  if (f) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) {
      fallo = fallo || 'fecha_mal_formada';
    } else {
      const p = f.split('-').map(Number);
      const d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
      const real = d.getUTCFullYear() === p[0] && d.getUTCMonth() === p[1] - 1 && d.getUTCDate() === p[2];
      const hoyP = String(cfg.hoy).split('-').map(Number);
      const dif = (Date.UTC(p[0], p[1] - 1, p[2]) - Date.UTC(hoyP[0], hoyP[1] - 1, hoyP[2])) / 86400000;
      if (!real) fallo = fallo || 'fecha_inexistente';
      else if (dif < 0) fallo = fallo || 'fecha_pasada';
      else if (dif > HORIZONTE) fallo = fallo || 'fecha_fuera_de_horizonte';
      else fecha = f;
    }
  }

  // Algunos modelos devuelven la confianza en porcentaje: se normaliza a 0-1
  let c = Number(ia.confianza);
  if (!isNaN(c) && c > 1 && c <= 100) c = c / 100;
  confianza = isNaN(c) ? 0 : Math.max(0, Math.min(1, c));

  if (confianza < PISO_CONF) {
    // Ni la intencion es fiable: al menu numerico
    fallo = fallo || 'confianza_baja';
    intencion = 'otro'; materia = ''; fecha = '';
  } else if (confianza < MIN_CONF) {
    // La intencion sirve para enrutar (el wizard confirma todo despues),
    // pero no se prellena nada sin confianza suficiente.
    if (materia || fecha) fallo = fallo || 'confianza_insuficiente_para_prellenar';
    materia = ''; fecha = '';
  }
}

// ---- 4. Traducir la interpretacion a la entrada que habria escrito un humano ----
// El motor determinista no sabe que existio una IA: recibe exactamente lo mismo.
const salida = Object.assign({}, ctx);
salida.ia_usada = true;
salida.ia_intencion = intencion;
salida.ia_materia = materia;
salida.ia_fecha = fecha;
salida.ia_confianza = confianza;
salida.ia_fallo = fallo;
salida.ia_texto_original = String(ctx.texto || '').slice(0, 200);

const catalogo = Array.isArray(ctx.ia_catalogo) ? ctx.ia_catalogo : [];
const datosBase = Object.assign({}, ctx.datos || {}, { materias: catalogo });
let aviso = '';

if (intencion === 'solicitar' && materia && fecha) {
  // Entra directo al motor de busqueda con la fecha como si el usuario la hubiera escrito
  salida.ruta = 'SOLICITAR';
  salida.submodo = 'fecha';
  salida.texto = fecha;
  salida.pantalla_previa = 'SOL_FECHA';
  salida.datos = Object.assign({}, datosBase, { materia: materia });
  aviso = 'Entendi: ' + materia + ' para el ' + fecha + '.';
} else if (intencion === 'solicitar' && materia) {
  // Se convierte en el numero del menu: mismo camino que el wizard numerico
  const idx = catalogo.findIndex(m => norm(m) === norm(materia));
  salida.ruta = 'SOLICITAR';
  salida.submodo = 'materia';
  salida.texto = String(idx + 1);
  salida.pantalla_previa = 'SOL_MATERIA';
  salida.datos = datosBase;
  aviso = 'Entendi que necesitas ' + materia + '.';
} else if (intencion === 'solicitar' && fecha && String(ctx.pantalla_previa) === 'SOL_FECHA') {
  salida.ruta = 'SOLICITAR';
  salida.submodo = 'fecha';
  salida.texto = fecha;
  aviso = 'Entendi la fecha ' + fecha + '.';
} else if (intencion === 'solicitar') {
  salida.ruta = 'SOLICITAR';
  salida.submodo = 'iniciar';
  salida.datos = datosBase;
  aviso = 'Entendi que quieres agendar una asesoria.';
} else if (intencion === 'consultar') {
  salida.ruta = 'CONSULTAR'; salida.submodo = 'listar';
  aviso = 'Entendi que quieres ver tus tutorias.';
} else if (intencion === 'cancelar') {
  salida.ruta = 'CANCELAR'; salida.submodo = 'listar';
  aviso = 'Entendi que quieres cancelar una tutoria.';
} else if (intencion === 'ayuda') {
  salida.ruta = 'MENU'; salida.submodo = 'ayuda';
} else {
  // IA-08: no se entendio nada utilizable -> el menu numerico de siempre
  salida.ruta = 'MENU';
  salida.submodo = ctx.pantalla_previa === 'SOL_MATERIA' ? 'no_reconocido'
                 : (ctx.pantalla_previa === 'SOL_FECHA' ? 'no_reconocido' : 'no_reconocido');
  if (ctx.pantalla_previa === 'SOL_MATERIA') { salida.ruta = 'SOLICITAR'; salida.submodo = 'materia'; }
  if (ctx.pantalla_previa === 'SOL_FECHA')   { salida.ruta = 'SOLICITAR'; salida.submodo = 'fecha'; }
}

salida.ia_aviso = aviso;
return [{ json: salida }];
